begin;

select extensions.no_plan();

-- Synthetic-only P4-03 authorization graph.
insert into auth.users (id, instance_id, aud, role, email, encrypted_password, email_confirmed_at, raw_app_meta_data, raw_user_meta_data, created_at, updated_at)
values
  ('b6100000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','owner-a@p403.example.test','',statement_timestamp(),'{}','{}',statement_timestamp(),statement_timestamp()),
  ('b6100000-0000-0000-0000-000000000002','00000000-0000-0000-0000-000000000000','authenticated','authenticated','staff-a@p403.example.test','',statement_timestamp(),'{}','{}',statement_timestamp(),statement_timestamp()),
  ('b6100000-0000-0000-0000-000000000003','00000000-0000-0000-0000-000000000000','authenticated','authenticated','owner-b@p403.example.test','',statement_timestamp(),'{}','{}',statement_timestamp(),statement_timestamp());
insert into public.organizations (id,legal_name,business_name,slug) values
  ('b6200000-0000-0000-0000-000000000001','P403 Synthetic A Inc.','P403 A','p403-a'),
  ('b6200000-0000-0000-0000-000000000002','P403 Synthetic B Inc.','P403 B','p403-b');
insert into public.organization_members (id,organization_id,user_id,membership_status,joined_at) values
  ('b6300000-0000-0000-0000-000000000001','b6200000-0000-0000-0000-000000000001','b6100000-0000-0000-0000-000000000001','active',statement_timestamp()),
  ('b6300000-0000-0000-0000-000000000002','b6200000-0000-0000-0000-000000000001','b6100000-0000-0000-0000-000000000002','active',statement_timestamp()),
  ('b6300000-0000-0000-0000-000000000003','b6200000-0000-0000-0000-000000000002','b6100000-0000-0000-0000-000000000003','active',statement_timestamp());
insert into public.patients (id, organization_id, patient_number, first_name, last_name, birth_date) values
  ('b6400000-0000-0000-0000-000000000001', 'b6200000-0000-0000-0000-000000000001', 'P403-A-0001', 'Synthetic', 'Patient A', date '2015-01-01'),
  ('b6400000-0000-0000-0000-000000000002', 'b6200000-0000-0000-0000-000000000002', 'P403-B-0001', 'Foreign', 'Patient B', date '1980-01-01');

select extensions.columns_are('public','file_objects',array['id','organization_id','patient_id','object_key','mime_type','size_bytes','checksum_sha256','uploaded_by','status','version','created_at','updated_at','archived_at'],'file_objects has only the approved P4-03 metadata fields');
select extensions.is((select count(*)::integer from information_schema.columns where table_schema='public' and table_name='file_objects' and column_name ~* 'price|cost|fee|amount|first_name|last_name|middle_name|birth|address|phone|mobile|email|notes|description'),'0'::integer,'file_objects stores transfer metadata only and no patient-identifying columns');
select extensions.ok((select relrowsecurity from pg_class where oid='public.file_objects'::regclass),'file_objects has RLS enabled');
select extensions.ok(not exists(select 1 from (values(0::oid),((select oid from pg_roles where rolname='anon')),((select oid from pg_roles where rolname='authenticated')),((select oid from pg_roles where rolname='service_role'))) as role(role_oid) cross join (values('SELECT'),('INSERT'),('UPDATE'),('DELETE'),('TRUNCATE'),('REFERENCES'),('TRIGGER')) as privilege(name) where has_table_privilege(role.role_oid,'public.file_objects',privilege.name)),'PUBLIC, anon, authenticated, and service_role have no file_objects privileges');
select extensions.is((select count(*)::integer from pg_policies where schemaname='public' and tablename='file_objects'),1,'exactly one fail-closed visibility policy exists');
select extensions.is((select policyname from pg_policies where schemaname='public' and tablename='file_objects'),'file_objects_select_shared_directory','the visibility policy is the patient directory read policy');
select extensions.is((select roles::text from pg_policies where schemaname='public' and tablename='file_objects'),'{authenticated}','only authenticated is named by the visibility policy');
select extensions.ok(exists(select 1 from pg_indexes where schemaname='public' and indexname='file_objects_organization_patient_status_idx'),'file_objects has a tenant/patient/status access-path index');
select extensions.is(
  (select string_agg(attribute.attname, ',' order by index_column.ordinality)
   from pg_index as index_definition
   join pg_class as index_relation on index_relation.oid = index_definition.indexrelid
   join unnest(index_definition.indkey) with ordinality as index_column(attribute_number, ordinality) on true
   join pg_attribute as attribute on attribute.attrelid = index_definition.indrelid and attribute.attnum = index_column.attribute_number
   where index_relation.relname = 'file_objects_organization_patient_status_idx'),
  'organization_id,patient_id,status',
  'access-path index uses the required tenant/patient/status column order'
);

select extensions.lives_ok($$insert into public.file_objects (id, organization_id, patient_id, object_key, mime_type, size_bytes, checksum_sha256, uploaded_by) values ('b6500000-0000-0000-0000-000000000001','b6200000-0000-0000-0000-000000000001','b6400000-0000-0000-0000-000000000001','org/b6200000-0000-0000-0000-000000000001/patients/b6400000-0000-0000-0000-000000000001/files/b6500000-0000-0000-0000-000000000001','application/pdf',1024,'0f1e2d3c4b5a69788796a5b4c3d2e1f00f1e2d3c4b5a69788796a5b4c3d2e1f0','b6100000-0000-0000-0000-000000000001')$$,'a well-scoped same-tenant file row inserts cleanly');
select extensions.is((select version from public.file_objects where id='b6500000-0000-0000-0000-000000000001'),1,'new file rows start at optimistic version 1');
select extensions.is((select status from public.file_objects where id='b6500000-0000-0000-0000-000000000001'),'pending','new file rows start pending upload confirmation');

select extensions.throws_ok($$insert into public.file_objects (organization_id, patient_id, object_key, mime_type, size_bytes, checksum_sha256, uploaded_by) values ('b6200000-0000-0000-0000-000000000001','b6400000-0000-0000-0000-000000000001','org/../patients/b6400000-0000-0000-0000-000000000001/files/b6500000-0000-0000-0000-000000000002','application/pdf',1024,'0f1e2d3c4b5a69788796a5b4c3d2e1f00f1e2d3c4b5a69788796a5b4c3d2e1f0','b6100000-0000-0000-0000-000000000001')$$,'23514','new row for relation "file_objects" violates check constraint "file_objects_object_key_format_check"','path-traversal keys are rejected at the format boundary');
select extensions.throws_ok($$insert into public.file_objects (organization_id, patient_id, object_key, mime_type, size_bytes, checksum_sha256, uploaded_by) values ('b6200000-0000-0000-0000-000000000001','b6400000-0000-0000-0000-000000000001','ORG/b6200000-0000-0000-0000-000000000001/patients/b6400000-0000-0000-0000-000000000001/files/b6500000-0000-0000-0000-000000000003','application/pdf',1024,'0f1e2d3c4b5a69788796a5b4c3d2e1f00f1e2d3c4b5a69788796a5b4c3d2e1f0','b6100000-0000-0000-0000-000000000001')$$,'23514','new row for relation "file_objects" violates check constraint "file_objects_object_key_format_check"','non-lowercase-hex keys are rejected at the format boundary');
select extensions.throws_ok($$insert into public.file_objects (organization_id, patient_id, object_key, mime_type, size_bytes, checksum_sha256, uploaded_by) values ('b6200000-0000-0000-0000-000000000001','b6400000-0000-0000-0000-000000000001','org/b6200000-0000-0000-0000-000000000001/patients/b6400000-0000-0000-0000-000000000001/b6500000-0000-0000-0000-000000000003','application/pdf',1024,'0f1e2d3c4b5a69788796a5b4c3d2e1f00f1e2d3c4b5a69788796a5b4c3d2e1f0','b6100000-0000-0000-0000-000000000001')$$,'23514','new row for relation "file_objects" violates check constraint "file_objects_object_key_format_check"','keys missing the files segment are rejected at the format boundary');
select extensions.throws_ok($$insert into public.file_objects (organization_id, patient_id, object_key, mime_type, size_bytes, checksum_sha256, uploaded_by) values ('b6200000-0000-0000-0000-000000000001','b6400000-0000-0000-0000-000000000001','org/b6200000-0000-0000-0000-000000000002/patients/b6400000-0000-0000-0000-000000000001/files/b6500000-0000-0000-0000-000000000002','application/pdf',1024,'0f1e2d3c4b5a69788796a5b4c3d2e1f00f1e2d3c4b5a69788796a5b4c3d2e1f0','b6100000-0000-0000-0000-000000000001')$$,'23514','new row for relation "file_objects" violates check constraint "file_objects_object_key_scope_check"','keys naming a foreign org segment are rejected even when well-formed');
select extensions.throws_ok($$insert into public.file_objects (organization_id, patient_id, object_key, mime_type, size_bytes, checksum_sha256, uploaded_by) values ('b6200000-0000-0000-0000-000000000001','b6400000-0000-0000-0000-000000000001','org/b6200000-0000-0000-0000-000000000001/patients/b6400000-0000-0000-0000-000000000002/files/b6500000-0000-0000-0000-000000000002','application/pdf',1024,'0f1e2d3c4b5a69788796a5b4c3d2e1f00f1e2d3c4b5a69788796a5b4c3d2e1f0','b6100000-0000-0000-0000-000000000001')$$,'23514','new row for relation "file_objects" violates check constraint "file_objects_object_key_scope_check"','keys naming a foreign patient segment are rejected even when well-formed');

select extensions.throws_ok($$insert into public.file_objects (organization_id, patient_id, object_key, mime_type, size_bytes, checksum_sha256, uploaded_by) values ('b6200000-0000-0000-0000-000000000001','b6400000-0000-0000-0000-000000000001','org/b6200000-0000-0000-0000-000000000001/patients/b6400000-0000-0000-0000-000000000001/files/b6500000-0000-0000-0000-000000000004','application/pdf',0,'0f1e2d3c4b5a69788796a5b4c3d2e1f00f1e2d3c4b5a69788796a5b4c3d2e1f0','b6100000-0000-0000-0000-000000000001')$$,'23514','new row for relation "file_objects" violates check constraint "file_objects_size_positive_check"','empty uploads cannot commit');
select extensions.throws_ok($$insert into public.file_objects (organization_id, patient_id, object_key, mime_type, size_bytes, checksum_sha256, uploaded_by) values ('b6200000-0000-0000-0000-000000000001','b6400000-0000-0000-0000-000000000001','org/b6200000-0000-0000-0000-000000000001/patients/b6400000-0000-0000-0000-000000000001/files/b6500000-0000-0000-0000-000000000004','application/pdf',-5,'0f1e2d3c4b5a69788796a5b4c3d2e1f00f1e2d3c4b5a69788796a5b4c3d2e1f0','b6100000-0000-0000-0000-000000000001')$$,'23514','new row for relation "file_objects" violates check constraint "file_objects_size_positive_check"','negative sizes cannot commit');
select extensions.throws_ok($$insert into public.file_objects (organization_id, patient_id, object_key, mime_type, size_bytes, checksum_sha256, uploaded_by) values ('b6200000-0000-0000-0000-000000000001','b6400000-0000-0000-0000-000000000001','org/b6200000-0000-0000-0000-000000000001/patients/b6400000-0000-0000-0000-000000000001/files/b6500000-0000-0000-0000-000000000004','application/pdf',1024,'tooshort','b6100000-0000-0000-0000-000000000001')$$,'23514','new row for relation "file_objects" violates check constraint "file_objects_checksum_format_check"','checksums must be exactly 64 lowercase hex characters');
select extensions.throws_ok($$insert into public.file_objects (organization_id, patient_id, object_key, mime_type, size_bytes, checksum_sha256, uploaded_by) values ('b6200000-0000-0000-0000-000000000001','b6400000-0000-0000-0000-000000000001','org/b6200000-0000-0000-0000-000000000001/patients/b6400000-0000-0000-0000-000000000001/files/b6500000-0000-0000-0000-000000000004','application/pdf',1024,'0F1E2D3C4B5A69788796A5B4C3D2E1F00F1E2D3C4B5A69788796A5B4C3D2E1F0','b6100000-0000-0000-0000-000000000001')$$,'23514','new row for relation "file_objects" violates check constraint "file_objects_checksum_format_check"','uppercase checksums are rejected');
select extensions.throws_ok($$insert into public.file_objects (organization_id, patient_id, object_key, mime_type, size_bytes, checksum_sha256, uploaded_by, status) values ('b6200000-0000-0000-0000-000000000001','b6400000-0000-0000-0000-000000000001','org/b6200000-0000-0000-0000-000000000001/patients/b6400000-0000-0000-0000-000000000001/files/b6500000-0000-0000-0000-000000000004','application/pdf',1024,'0f1e2d3c4b5a69788796a5b4c3d2e1f00f1e2d3c4b5a69788796a5b4c3d2e1f0','b6100000-0000-0000-0000-000000000001','deleted')$$,'23514','new row for relation "file_objects" violates check constraint "file_objects_status_check"','invented lifecycle states are rejected');
select extensions.throws_ok($$insert into public.file_objects (organization_id, patient_id, object_key, mime_type, size_bytes, checksum_sha256, uploaded_by, status) values ('b6200000-0000-0000-0000-000000000001','b6400000-0000-0000-0000-000000000001','org/b6200000-0000-0000-0000-000000000001/patients/b6400000-0000-0000-0000-000000000001/files/b6500000-0000-0000-0000-000000000004','application/pdf',1024,'0f1e2d3c4b5a69788796a5b4c3d2e1f00f1e2d3c4b5a69788796a5b4c3d2e1f0','b6100000-0000-0000-0000-000000000001','archived')$$,'23514','new row for relation "file_objects" violates check constraint "file_objects_archive_state_check"','archived state requires an archive timestamp');
select extensions.throws_ok($$insert into public.file_objects (organization_id, patient_id, object_key, mime_type, size_bytes, checksum_sha256, uploaded_by, archived_at) values ('b6200000-0000-0000-0000-000000000001','b6400000-0000-0000-0000-000000000001','org/b6200000-0000-0000-0000-000000000001/patients/b6400000-0000-0000-0000-000000000001/files/b6500000-0000-0000-0000-000000000004','application/pdf',1024,'0f1e2d3c4b5a69788796a5b4c3d2e1f00f1e2d3c4b5a69788796a5b4c3d2e1f0','b6100000-0000-0000-0000-000000000001',statement_timestamp())$$,'23514','new row for relation "file_objects" violates check constraint "file_objects_archive_state_check"','an unarchived row cannot carry an archive timestamp');
select extensions.throws_ok($$insert into public.file_objects (organization_id, patient_id, object_key, mime_type, size_bytes, checksum_sha256, uploaded_by) values ('b6200000-0000-0000-0000-000000000001','b6400000-0000-0000-0000-000000000001','org/b6200000-0000-0000-0000-000000000001/patients/b6400000-0000-0000-0000-000000000001/files/b6500000-0000-0000-0000-000000000004','',1024,'0f1e2d3c4b5a69788796a5b4c3d2e1f00f1e2d3c4b5a69788796a5b4c3d2e1f0','b6100000-0000-0000-0000-000000000001')$$,'23514','new row for relation "file_objects" violates check constraint "file_objects_mime_type_bounded_check"','blank MIME types cannot commit');
select extensions.throws_ok($$insert into public.file_objects (organization_id, patient_id, object_key, mime_type, size_bytes, checksum_sha256, uploaded_by) values ('b6200000-0000-0000-0000-000000000001','b6400000-0000-0000-0000-000000000001','org/b6200000-0000-0000-0000-000000000001/patients/b6400000-0000-0000-0000-000000000001/files/b6500000-0000-0000-0000-000000000004','garbage',1024,'0f1e2d3c4b5a69788796a5b4c3d2e1f00f1e2d3c4b5a69788796a5b4c3d2e1f0','b6100000-0000-0000-0000-000000000001')$$,'23514','new row for relation "file_objects" violates check constraint "file_objects_mime_type_bounded_check"','non type/subtype MIME tokens cannot commit');

select extensions.throws_ok($$insert into public.file_objects (organization_id, patient_id, object_key, mime_type, size_bytes, checksum_sha256, uploaded_by) values ('b6200000-0000-0000-0000-000000000001','b6400000-0000-0000-0000-000000000002','org/b6200000-0000-0000-0000-000000000001/patients/b6400000-0000-0000-0000-000000000002/files/b6500000-0000-0000-0000-000000000005','application/pdf',1024,'0f1e2d3c4b5a69788796a5b4c3d2e1f00f1e2d3c4b5a69788796a5b4c3d2e1f0','b6100000-0000-0000-0000-000000000001')$$,'23503',null,'foreign-org patients fail the tenant-safe composite patient foreign key');
select extensions.throws_ok($$insert into public.file_objects (organization_id, patient_id, object_key, mime_type, size_bytes, checksum_sha256, uploaded_by) values ('b6200000-0000-0000-0000-000000000001','b6400000-0000-0000-0000-000000000001','org/b6200000-0000-0000-0000-000000000001/patients/b6400000-0000-0000-0000-000000000001/files/b6500000-0000-0000-0000-000000000005','application/pdf',1024,'0f1e2d3c4b5a69788796a5b4c3d2e1f00f1e2d3c4b5a69788796a5b4c3d2e1f0','b6100000-0000-0000-0000-000000000003')$$,'23503',null,'foreign-org uploaders fail the tenant-safe composite member foreign key');
select extensions.throws_ok($$insert into public.file_objects (id, organization_id, patient_id, object_key, mime_type, size_bytes, checksum_sha256, uploaded_by) values ('b6500000-0000-0000-0000-000000000009','b6200000-0000-0000-0000-000000000001','b6400000-0000-0000-0000-000000000001','org/b6200000-0000-0000-0000-000000000001/patients/b6400000-0000-0000-0000-000000000001/files/b6500000-0000-0000-0000-000000000001','application/pdf',1024,'0f1e2d3c4b5a69788796a5b4c3d2e1f00f1e2d3c4b5a69788796a5b4c3d2e1f0','b6100000-0000-0000-0000-000000000001')$$,'23505','duplicate key value violates unique constraint "file_objects_object_key_key"','object keys are globally unique so one stored byte sequence has one metadata row');

set local role authenticated;
select set_config('request.jwt.claim.role','authenticated',true);
select set_config('request.jwt.claim.sub','b6100000-0000-0000-0000-000000000001',true);
select set_config('request.jwt.claims','{"aal":"aal1"}',true);
select extensions.throws_ok($$select * from public.file_objects$$,'42501',null,'authenticated direct file_objects SELECT is privilege-denied');
select extensions.throws_ok($$insert into public.file_objects (organization_id, patient_id, object_key, mime_type, size_bytes, checksum_sha256, uploaded_by) values ('b6200000-0000-0000-0000-000000000001','b6400000-0000-0000-0000-000000000001','org/b6200000-0000-0000-0000-000000000001/patients/b6400000-0000-0000-0000-000000000001/files/b6500000-0000-0000-0000-000000000007','application/pdf',1024,'0f1e2d3c4b5a69788796a5b4c3d2e1f00f1e2d3c4b5a69788796a5b4c3d2e1f0','b6100000-0000-0000-0000-000000000001')$$,'42501',null,'authenticated direct file_objects INSERT is privilege-denied');
reset role;

with test_failures as (select finish from extensions.finish() where finish !~ '^1\.\.[0-9]+$')
select case when count(*)=0 then 'P1_TEST_PASS' else string_agg(finish,E'\n') end as p1_test_result from test_failures;

rollback;
